import {escapeHtml as esc} from './components.js';
import {percentage,time} from './data.js';
import {filterMonthlyFlow,monthLabel} from './monthly-flow-model.js';
import {universes} from './sector-map.js';
const direction=v=>v>0?'up':v<0?'negative':'';
export function mountMonthlyFlow(root,{initialMarket='KR',initialIndex,initialActive=true,onData,onMode,onMarket}){
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit'}).format(new Date());
 let market=initialMarket,indexId=initialIndex||universes[market][0][0],month=today,day='',filter='all',data=null,active=initialActive,loading=false,abort,version=0;
 function render(){
  const optionsOpen=Boolean(root.querySelector?.('.flow-options')?.open),focused=root.ownerDocument?.activeElement;
  const focusData=focused&&root.contains?.(focused)?{id:focused.id,type:focused.type,dataset:{...focused.dataset}}:null;
  const s=data?.summary||{},leader=data?.items?.find(i=>i.id===s.leader),bench=data?.benchmark,dates=data?.availableDates||[];
  const card=(key,label,value,note,disabled=false)=>`<button class="flow-card ${filter===key?'selected':''}" data-flow-filter="${esc(key)}" aria-pressed="${filter===key}" ${disabled?'disabled':''}><span>${label}</span><strong>${value}</strong><small>${esc(note)}</small></button>`;
  root.innerHTML=`<div class="flow-mode-bar"><div class="flow-mode-switch" role="group" aria-label="시장 집계 기간"><button data-flow-mode="day" aria-pressed="${!active}">일간 흐름</button><button data-flow-mode="month" aria-pressed="${active}">월간 흐름</button></div><span class="flow-mode-caption">${active?esc(month+' · '+(data?.startDate&&data?.baseDate?data.startDate+' → '+data.baseDate:'기준일 확인 중')+' · 월 누적 수익률'):'일간 등락률 · 시세 기준은 각 패널에 표시'}</span></div><details class="flow-options" ${optionsOpen?'open':''}><summary id="flow-options-summary">월간 기간·시장·필터 <span>${active?'순위·섹터맵에 적용 중':'필요할 때 펼쳐보세요'}</span></summary><div class="flow-options-body"><div class="flow-heading"><h2>월간 시장 흐름</h2></div><div class="flow-controls"><div class="segmented" role="group" aria-label="월간 시장">${[['KR','국내'],['US','미국']].map(([id,n])=>`<button data-flow-market="${id}" aria-pressed="${market===id}" class="${market===id?'active':''}">${n}</button>`).join('')}</div><label class="sr-only" for="flow-index">분석 대상 지수</label><select id="flow-index">${universes[market].map(([id,n])=>`<option value="${id}" ${id===indexId?'selected':''}>${n}</option>`).join('')}</select><label>분석 월 <input type="month" aria-label="분석 월" value="${month}" min="2000-01" max="${today}"></label><span class="flow-basis">${esc(monthLabel(month,data?.baseDate))} · ${market==='KR'?'한국':'미국'} 거래일</span></div><div class="flow-state" role="status">${loading?'저장된 일봉을 확인하고 있어요':data?.status==='error'||data?.status==='restricted'?esc(data.message):data?.stale?'갱신 실패 · 마지막 저장 집계':data?.status==='empty'?esc(data.message):''}</div><p class="flow-price-basis">${market==='US'?'Finviz 공급 종가 기준 · 수정주가 여부 미확인':'공급 종가 기준 · 가격 기준 변경이 의심되는 구간 제외'}</p><div class="flow-cards" ${loading?'aria-busy="true"':''}>
  ${card('underperform','지수 수익률',`<span class="${direction(bench?.changePct)}">${percentage(bench?.changePct)}</span>`,Number.isFinite(bench?.changePct)?(data.universe+' · 지수 이하 종목 보기'):bench?.message||'기준 지수 일봉 확인 중',!Number.isFinite(bench?.changePct))}
  ${card('up','상승 확산도',Number.isFinite(s.upRatio)?s.upRatio.toFixed(1)+'%':'—',s.used?'상승 '+s.up+' · 보합 '+s.flat+' · 하락 '+s.down:'집계 가능한 종목 없음',!s.used)}
  ${card('above-median','종목 중간값',`<span class="${direction(s.median)}">${percentage(s.median)}</span>`,'중간값 이상 종목 보기',!s.used)}
  ${card('sector:'+(leader?.id||''),'주도 섹터',esc(leader?.name||'—'),leader?'상승 '+leader.upRatio.toFixed(0)+'% · 중간 '+percentage(leader.median):'상승 비율 50% 초과·중간값 양수 섹터 없음',!leader)}
  ${card('outperform','지수 대비 강한 종목',s.outperform===null||s.outperform===undefined?'—':s.outperform+'개','같은 시작일·종료일 비교',!Number.isFinite(bench?.changePct))}
 </div><div class="flow-bottom"><div class="flow-filters" role="group" aria-label="월간 종목 필터">${[['all','전체'],['up','상승'],['flat','보합'],['down','하락']].map(([key,n])=>`<button data-flow-filter="${key}" aria-pressed="${filter===key}">${n}</button>`).join('')}<span>${active?'순위·맵에 적용 중':'일간 순위 표시 중'} · 집계 ${s.used||0} / 대상 ${data?.target||0}개 · ETF 제외</span><b class="flow-filter-label">${esc(filter==='all'?'':filter==='above-median'?'중간값 이상':filter==='outperform'?'지수 초과':filter==='underperform'?'지수 이하':filter.startsWith('sector:')?data?.items?.find(i=>i.id===filter.slice(7))?.name||'섹터 선택':'')}</b></div>${dates.length>1?`<label class="flow-slider">기준 거래일 <input type="range" aria-label="월 누적 기준 거래일" min="0" max="${dates.length-1}" step="1" value="${Math.max(0,dates.indexOf(data.baseDate))}" aria-valuetext="${data.baseDate}"><output>${data.baseDate}</output></label>`:''}</div><details class="flow-details"><summary>계산 기준·출처·제외 항목</summary><p>${esc(data?.calculation||'전월 마지막 거래일 종가 대비 선택일 종가')}</p><p>${esc(data?.membershipNote||'')} ${esc(data?.adjustmentNote||'')}</p><p>${esc(data?.source||'')} · ${esc(data?.startDate||'—')} → ${esc(data?.baseDate||'—')} · 집계 ${data?.calculatedAt?time(data.calculatedAt,true):'없음'}</p><p>${esc(data?.areaNote||'')} · 주도 섹터는 상승 비율, 중간값 순으로 선정합니다.</p>${(data?.excluded||[]).length?`<p>${data.excluded.length}개 제외</p><ul>${data.excluded.map(x=>`<li>${esc(x.name||x.id)} · ${esc(x.reason)}</li>`).join('')}</ul>`:''}</details></div></details>`;
  if(focusData){const target=[...root.querySelectorAll('button,input,select,summary')].find(el=>focusData.id?el.id===focusData.id:Object.keys(focusData.dataset).length?Object.entries(focusData.dataset).every(([k,v])=>el.dataset[k]===v):el.type===focusData.type);target?.focus({preventScroll:true});}
 }
 function emit(){if(active){onMode?.(true);onData(filterMonthlyFlow(data||{analysis:'monthly',market,indexId,month,items:[],stocks:[],status:loading?'loading':'empty',message:loading?'월간 일봉을 확인하고 있어요':'집계 데이터 없음'},filter),{market,indexId,month});}}
 async function load(){abort?.abort();abort=new AbortController();const n=++version;loading=true;const previous=data?.market===market&&data?.indexId===indexId&&data?.month===month&&(data?.requestedDay||'')===day?data:null;data=previous;render();if(!previous)emit();try{const response=await fetch('/api/monthly-flow?'+new URLSearchParams({market,indexId,month,...(day?{day}:{})}),{signal:abort.signal});if(!response.ok)throw Error();const result=await response.json();if(n!==version)return;data=result;}catch(e){if(n!==version)return;data=previous?{...previous,stale:true}: {status:'error',items:[],stocks:[],analysis:'monthly',market,indexId,month,message:'월간 데이터를 불러오지 못했습니다. 새로고침해 주세요.'};}loading=false;render();emit();}
 function setMode(next){
  if(active===Boolean(next))return;active=Boolean(next);render();
  if(active){if(data||loading)emit();else load();}else onMode?.(false);
 }
 function select(next){const nextIndex=next.indexId||(next.market===market?indexId:universes[next.market][0][0]);if(next.market===market&&nextIndex===indexId)return;market=next.market;indexId=nextIndex;filter='all';day='';active=true;onMarket?.(market);load();}
 root.addEventListener('click',e=>{const f=e.target.closest('[data-flow-filter]'),m=e.target.closest('[data-flow-market]');if(f){filter=f.dataset.flowFilter;active=true;render();emit();}else if(m)select({market:m.dataset.flowMarket,indexId:universes[m.dataset.flowMarket][0][0]});else if(e.target.closest('[data-flow-mode]'))setMode(e.target.closest('[data-flow-mode]').dataset.flowMode==='month');});
 root.addEventListener('toggle',e=>{if(e.target.matches?.('.flow-options')&&e.target.open&&!data&&!loading)load();},true);
 root.addEventListener('input',e=>{if(e.target.type==='range'){const date=data?.availableDates?.[Number(e.target.value)];e.target.setAttribute('aria-valuetext',date);root.querySelector('output').textContent=date;}});
 root.addEventListener('change',e=>{if(e.target.id==='flow-index')select({market,indexId:e.target.value});else if(e.target.type==='month'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)&&e.target.value<=today){month=e.target.value;filter='all';day='';active=true;load();}else if(e.target.type==='range'){day=data?.availableDates?.[Number(e.target.value)]||'';load();}});
 render();return {load,select,setMode,isActive:()=>active,refresh(){if(!loading)load();},deactivate(){setMode(false);},filter(value){filter=value;active=true;render();emit();}};
}
